  void UnPackTo(PHBT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  static ::flatbuffers::Offset<PHB> Pack(::flatbuffers::FlatBufferBuilder &_fbb, const PHBT* _o, const ::flatbuffers::rehasher_function_t *_rehasher = nullptr);
